use vstd::prelude::*;

verus! {
    fn smallest_num(nums: &Vec<i32>) -> (min: i32)
        requires
            !nums.is_empty(),
        ensures
            min <= *nums.iter().max().unwrap(),
            nums.contains(&min),
    {
        let mut min: i32 = nums[0]; // Initialize min with the first element
        let mut idx: usize = 1; // Start from the second element

        while idx < nums.len()
            invariant
                idx <= nums.len(),
                min <= nums[0..idx].iter().cloned().min().unwrap(),
                nums.contains(&min),
            decreases nums.len() - idx,
        {
            if nums[idx] < min {
                min = nums[idx]; // Update min if a smaller value is found
            }
            idx = idx + 1; // Move to the next element
        }
        min
    }
}
